class StartArchiveApiTest {
    @Test fun archiveUsesArchiveIdAndRemainsIndependentOfSeasonSeries() = runTest {
        val json = JsonProviderBase().provide()
        val paths = mutableListOf<String>()
        val client = HttpClient(MockEngine { request ->
            paths += request.url.encodedPath
            assertEquals(HttpMethod.Get, request.method)
            respond(response, headers = headersOf(HttpHeaders.ContentType, "application/json"))
        }) { expectSuccess = true; defaultRequest { url("https://api.sportsauce.ru/") } }
        try {
            val api = SportSauceNetworkStartsApi(object : HttpClientProvider {
                override fun provide(loggerEnabled: Boolean) = client
                override fun json() = json
            })
            val archive = api.fetchArchive(1)
            assertEquals(5, archive.count)
            assertEquals(listOf(29, 113, 164, 258, 318), archive.rows.map { it.id })
            assertEquals("2022-10-29T11:00:00.000Z", archive.rows.first().start_date)
            assertEquals("2026-10-25T10:00:00.000Z", archive.rows.last().start_date)
            api.fetchSeries(3)
            assertEquals(listOf("/start/1/related-start-archive", "/start/3/related-start-series"), paths)
        } finally { client.close() }
    }
